package com.xyz.question_bank_management_system.modules.agent.tool;
import com.xyz.question_bank_management_system.exception.*;import com.xyz.question_bank_management_system.modules.source.entity.SourceChunk;import com.xyz.question_bank_management_system.modules.source.mapper.SourceChunkMapper;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Component;import java.util.*;
@Component @RequiredArgsConstructor public class CourseRagSearchTool {private final SourceChunkMapper mapper;public List<Map<String,Object>> query(List<Long> knowledgePointIds){List<SourceChunk> rows=mapper.selectEvidenceForKnowledge(knowledgePointIds,20);if(rows.isEmpty())throw BizException.of(ErrorCode.EVIDENCE_INSUFFICIENT,"课程知识点缺少审核通过的 source_chunk 证据");return rows.stream().map(x->{Map<String,Object> m=new LinkedHashMap<>();m.put("evidenceId",x.getId());m.put("sourceId",x.getDocumentId());m.put("sourceType","SOURCE_CHUNK");m.put("evidenceText",x.getContent());m.put("supportedKnowledgePointIds",knowledgePointIds);return m;}).toList();}}
